using System;
using System.Linq;
using System.IO;
using UnityEngine;
public static class RoadMapExtendedTests {
 public static void Run(){MapCatalog.LockedRegion="eungye";MapCatalog.Load();var baseline=RoadMapRuntime.Baseline;var d=RoadMapDocument.Create(baseline);var valid=RoadMapValidator.Validate(baseline,d);if(valid.Any(i=>i.error))throw new Exception("Valid baseline rejected: "+string.Join("\n",valid.Where(i=>i.error).Take(10).Select(i=>i.ToString())));
  var lane=d.lanes.First(l=>!l.disabled&&l.change==0&&l.turn==0);float length=new AssistedRoadNetwork.Path(lane.points.Select(p=>p.V()).ToArray()).length;
  var speed=new RoadMapFacility{id="speed-test",kind="sign",type="제한속도",rule=true,laneId=lane.id,speed=20,startAt=0,endAt=length};d.facilities=new[]{speed};if(RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Valid speed rule rejected");var candidate=RoadMapComposer.Compose(baseline,d);if(RoadMapRules.SpeedLimit(candidate,lane.id,1)!=20)throw new Exception("Speed rule not shared");speed.endAt=length+1;if(!RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Out of range speed accepted");
  d=RoadMapDocument.Create(baseline);d.lanes[1].id=d.lanes[0].id;if(!RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Duplicate accepted");
  var p=new RoadMapSignalProgram{junctionId=baseline.junctionRules[0].id,groups=new[]{new RoadMapSignalGroup{id="g1",axis=0,sign=1},new RoadMapSignalGroup{id="g2",axis=1,sign=1}},stages=new[]{new RoadMapStage{groups=new[]{"g1","g2"}}}};d=RoadMapDocument.Create(baseline);d.signals=new[]{p};if(!RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Conflicting signal accepted");
  p.groups[1].pedestrian=true;if(!RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Vehicle pedestrian conflict accepted");
  string file=Path.GetFullPath("../../artifacts/road-map-editor-tests/atomic.json");d=RoadMapDocument.Create(baseline);RoadMapStore.Save(file,d);string bytes=File.ReadAllText(file);using(var locked=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){bool failed=false;try{RoadMapStore.Save(file,d);}catch{failed=true;}if(!failed)throw new Exception("Locked destination replaced");}if(File.ReadAllText(file)!=bytes)throw new Exception("Failed save corrupted previous file");
  d=RoadMapDocument.Create(baseline);var broken=new RoadMapSignalProgram{junctionId=baseline.junctionRules[0].id,groups=new[]{new RoadMapSignalGroup{id="walk",pedestrian=true}},stages=new[]{new RoadMapStage{groups=new[]{"walk"}}}};d.signals=new[]{broken};if(!RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Unbound walk accepted");var signal=new RoadMapSignalProgram{groups=new[]{new RoadMapSignalGroup{id="one",laneIds=new[]{"lane1"}},new RoadMapSignalGroup{id="two",laneIds=new[]{"lane2"}}},stages=new[]{new RoadMapStage{groups=new[]{"one"}},new RoadMapStage{groups=new[]{"two"}}}};if(signal.Movement(0,1,0,0,"lane2")!=SignalColor.Red||signal.Movement(0,1,0,0,"lane1")!=SignalColor.Green)throw new Exception("Per lane signal leaks");d=RoadMapDocument.Create(baseline);d.facilities=new RoadMapFacility[]{null};if(!RoadMapValidator.Validate(baseline,d).Any(i=>i.error))throw new Exception("Malformed facility accepted");d=RoadMapDocument.Create(baseline);var elevated=d.lanes.First(l=>!l.disabled&&l.points.Length>2);elevated.heights=new float[elevated.points.Length];elevated.heights[1]=.2f;var elevatedMap=RoadMapComposer.Compose(baseline,d);if(elevatedMap.hdEdges.First(l=>l.id==elevated.id).points[1].V().y!=.2f)throw new Exception("Elevation lost");Debug.Log("ROAD_MAP_EXTENDED_TESTS_OK baselineValid=true speed=true duplicates=true conflicts=true atomic=true");
 }
